package team.rustcraft.building;
import net.minecraft.block.Block;import net.minecraft.block.BlockState;import net.minecraft.entity.player.PlayerEntity;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.text.Text;import net.minecraft.util.*;import net.minecraft.util.hit.BlockHitResult;import net.minecraft.util.math.BlockPos;import net.minecraft.world.World;import team.rustcraft.api.building.ToolCupboardId;import team.rustcraft.api.death.WorldPosition;import team.rustcraft.api.player.PlayerId;import java.util.UUID;
public final class ToolCupboardBlock extends Block { public ToolCupboardBlock(Settings s){super(s);} @Override public void onPlaced(World w, BlockPos pos, BlockState state, net.minecraft.entity.LivingEntity placer, net.minecraft.item.ItemStack stack){ if(!w.isClient && placer instanceof ServerPlayerEntity p){ String wid=w.getRegistryKey().getValue().toString(); ToolCupboardId id=new ToolCupboardId("tc-"+UUID.randomUUID()); RustCraftBuildingMod.BUILDINGS.placeToolCupboard(id,new PlayerId(p.getUuid()),new WorldPosition(wid,pos.getX(),pos.getY(),pos.getZ()),true); RustCraftBuildingMod.INDEX.putToolCupboard(wid,pos,id);} } @Override public ActionResult onUse(BlockState state, World w, BlockPos pos, PlayerEntity player, Hand hand, BlockHitResult hit){ if(!w.isClient){ String wid=w.getRegistryKey().getValue().toString(); RustCraftBuildingMod.INDEX.toolCupboardAt(wid,pos).ifPresent(id -> { if(player.isSneaking()) RustCraftBuildingMod.BUILDINGS.authorizePlayer(id,new PlayerId(player.getUuid())); player.sendMessage(Text.literal("RustCraft Tool Cupboard: sneak-right-click authorizes you. Storage hook ready for inventory integration."),false);}); } return ActionResult.SUCCESS; }}
